import {crc32} from './project-zip.js';
// Images remain at the named external distributor, downloaded only on demand.
// Parse the pinned numeric array as data; never evaluate downloaded JavaScript.
export const PICO_ROM_ASSETS={
 RP2040:{revision:'RP2040 B1',bytes:16384,crc:0xbb547a1f,url:'https://cdn.jsdelivr.net/npm/rp2350js@2.0.1/dist/esm/bootroms/bootrom-rp2040-b1.js',sourceBytes:51387,sourceSHA256:'3b12b8d96ce62ac1237ab5b924a23199ea2b62ed198f8e1165961114a11575ef'},
 RP2350:{revision:'RP2350 A2',bytes:32768,crc:0x8ea874c3,url:'https://cdn.jsdelivr.net/npm/rp2350js@2.0.1/dist/esm/bootroms/bootrom-rp2350-a2.js',sourceBytes:102638,sourceSHA256:'1885190c1ad2ebca41a32a3e505774836b881ca3e2a3b4a2209e371c744802c8'}
};
export function decodePicoROMData(text,chip){const spec=PICO_ROM_ASSETS[chip];if(!spec)throw Error('ROM çipi geçersiz.');const match=/export const \w+ = new Uint32Array\(\[([\s\S]*?)\]\);/.exec(text);if(!match||!/^[\s,0-9a-fx]+$/i.test(match[1]))throw Error('ROM sağlayıcı veri biçimi geçersiz.');const words=match[1].split(',').map(s=>s.trim()).filter(Boolean);if(words.length*4!==spec.bytes||words.some(w=>!/^0x[\da-f]{1,8}$/i.test(w)))throw Error('ROM veri boyutu/değeri geçersiz.');const out=new Uint8Array(spec.bytes),view=new DataView(out.buffer);words.forEach((w,i)=>view.setUint32(i*4,Number(w),true));if(crc32(out)!==spec.crc)throw Error('ROM sağlama toplamı eşleşmiyor.');return out;}
export async function loadPicoROM(chip,{fetcher=fetch,cacheStorage=globalThis.caches}={}){const spec=PICO_ROM_ASSETS[chip];if(!spec)throw Error('ROM çipi geçersiz.');let cache=null;try{cache=await cacheStorage?.open('wirevo-pico-rom-pinned-1');}catch{}const cached=await cache?.match(spec.url);let response=cached||await fetcher(spec.url,{credentials:'omit',mode:'cors'});if(!response?.ok)throw Error('ROM indirilemedi; yerel ROM dosyası seçebilirsiniz.');const data=new Uint8Array(await response.arrayBuffer());if(data.length!==spec.sourceBytes)throw Error('ROM kaynağının boyutu değişmiş.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data)),b=>b.toString(16).padStart(2,'0')).join('');if(hash!==spec.sourceSHA256)throw Error('ROM kaynağının SHA-256 doğrulaması başarısız.');const rom=decodePicoROMData(new TextDecoder().decode(data),chip);if(!cached&&cache)try{await cache.put(spec.url,new Response(data,{headers:{'Content-Type':'text/plain'}}));}catch{}return rom;}
